// Valida a leitura, calcula a espera e o status e decide se há alerta (só na mudança de status).
const p = msg.payload || {};
const unidade = String(p.unidade || msg.topic.split("/")[2] || "").slice(0, 40);
const pessoas = Number(p.pessoas);
if (!unidade || typeof p.pessoas !== "number" || !Number.isInteger(pessoas) || pessoas < 0 || pessoas > 500) {
    return [null, null, {params: {$topico: msg.topic, $conteudo: JSON.stringify(p), $motivo: "contagem inválida"}}];
}
const MIN_POR_PESSOA = 1.8;              // tempo médio de atendimento por pessoa, em minutos
const espera = Math.round(pessoas * MIN_POR_PESSOA);
const status = espera <= 20 ? "tranquila" : (espera <= 45 ? "moderada" : "cheia");
msg.params = {$unidade: unidade, $pessoas: pessoas, $espera: espera, $status: status, $ts: p.ts || null};
node.status({fill: status === "cheia" ? "red" : (status === "moderada" ? "yellow" : "green"), shape: "dot",
             text: `${unidade}: ${pessoas} pessoas, ${espera} min`});
const chave = "status_" + unidade;
const anterior = flow.get(chave);
flow.set(chave, status);
let alerta = null;
if (status === "cheia" && anterior !== "cheia") {
    alerta = {tipo: "fila_cheia", local: unidade,
              texto: `Fila cheia na unidade ${unidade}: ${pessoas} pessoas, cerca de ${espera} min de espera. ` +
                     `O app já sugere a unidade com menos fila. Avalie abrir mais um guichê.`};
} else if (anterior === "cheia" && status !== "cheia") {
    alerta = {tipo: "fila_normalizada", local: unidade,
              texto: `A fila da unidade ${unidade} voltou ao normal: ${pessoas} pessoas, cerca de ${espera} min.`};
}
return [msg, alerta ? {payload: alerta} : null, null];

// Valida a leitura do DHT22 e alerta quando a unidade passa de 30 °C (volta ao normal abaixo de 28 °C).
const p = msg.payload || {};
const unidade = String(p.unidade || msg.topic.split("/")[2] || "").slice(0, 40);
const temp = Number(p.temp_c), umidade = Number(p.umidade);
if (!unidade || !Number.isFinite(temp) || temp < -10 || temp > 60) {
    return [null, null, {params: {$topico: msg.topic, $conteudo: JSON.stringify(p), $motivo: "temperatura inválida"}}];
}
msg.params = {$unidade: unidade, $temp: temp, $umidade: Number.isFinite(umidade) ? umidade : null};
node.status({fill: temp >= 30 ? "red" : "green", shape: "dot", text: `${unidade}: ${temp} °C`});
const chave = "calor_" + unidade;
const emAlerta = flow.get(chave) || false;
let alerta = null;
if (temp >= 30 && !emAlerta) {
    flow.set(chave, true);
    alerta = {tipo: "calor", local: unidade,
              texto: `Calor na unidade ${unidade}: ${temp} °C. Pessoas idosas esperando na fila: ofereça água e lugar para sentar.`};
} else if (temp <= 28 && emAlerta) {
    flow.set(chave, false);
}
return [msg, alerta ? {payload: alerta} : null, null];

// Registra presença e pedido de ajuda. Todo pedido de ajuda vira alerta para a equipe.
const p = msg.payload || {};
const partes = msg.topic.split("/");
const totem = String(p.totem || partes[2] || "").slice(0, 40);
const tipo = partes[3];
if (!totem || !["presenca", "ajuda"].includes(tipo)) {
    return [null, null, {params: {$topico: msg.topic, $conteudo: JSON.stringify(p), $motivo: "evento inválido"}}];
}
const valor = tipo === "ajuda" ? Boolean(p.ajuda) : Boolean(p.presente);
msg.params = {$totem: totem, $tipo: tipo, $valor: String(valor)};
let alerta = null;
if (tipo === "ajuda" && valor) {
    alerta = {tipo: "ajuda", local: totem,
              texto: `Pedido de ajuda no totem ${totem}. Um atendente deve ir até o totem.`};
}
node.status({fill: alerta ? "red" : "blue", shape: "dot", text: `${totem}: ${tipo}`});
return [msg, alerta ? {payload: alerta} : null, null];

// Grava todo alerta no banco e, se houver bot configurado, envia pelo Telegram.
const a = msg.payload;
const token = env.get("TELEGRAM_BOT_TOKEN");
const chat = env.get("TELEGRAM_CHAT_ID");
const canal = token && chat ? "telegram" : "somente_banco";
const gravar = {payload: {...a, canal}, params: {$tipo: a.tipo, $local: a.local, $texto: a.texto, $canal: canal}};
if (canal !== "telegram") {
    node.status({fill: "yellow", shape: "ring", text: "sem Telegram configurado: alerta só no banco"});
    return [gravar, null];
}
node.status({fill: "green", shape: "dot", text: `alerta ${a.tipo} enviado`});
const envio = {url: `https://api.telegram.org/bot${token}/sendMessage`, method: "POST",
               headers: {"content-type": "application/json"},
               payload: {chat_id: chat, text: `🔔 Vai de Primeira\n${a.texto}`}};
return [gravar, envio];

// Confere a resposta do Telegram. Falha não para o fluxo: o alerta já está no banco.
if (msg.statusCode !== 200) {
    node.warn(`Telegram respondeu ${msg.statusCode}: o alerta ficou registrado só no banco`);
    node.status({fill: "red", shape: "ring", text: `falha ${msg.statusCode}`});
} else {
    node.status({fill: "green", shape: "dot", text: "entregue"});
}
return null;
